template:
test -n '' && bcftools mpileup -Ou -f '' tests/fixtures/plan_inputs/default/sample.bam | bcftools call -m -v -Ob -o out/genotyping.raw.bcf && bcftools +tag2tag out/genotyping.raw.bcf -Ob -o out/genotyping.bcf -- --PL-to-GP && rm -f out/genotyping.raw.bcf && bcftools view -Oz -o out/genotyping.vcf.gz out/genotyping.bcf && bcftools index --force --tbi out/genotyping.vcf.gz && variant_count=$(bcftools view -H out/genotyping.vcf.gz | wc -l) && sample_count=$(bcftools query -l out/genotyping.vcf.gz | wc -l) && genotype_counts=$(bcftools query -f '[%GT	%GP
]' out/genotyping.vcf.gz | awk -v minimum_posterior="0.8" 'BEGIN{called=0; total=0} {total++; highest=0; n=split($2, probabilities, ","); for (i=1; i<=n; i++) if (probabilities[i]+0 > highest) highest=probabilities[i]+0; if ($1 != "./." && $1 != ".|." && $1 != "." && $2 != "." && highest >= minimum_posterior) called++} END{printf "%d %d %.12f", called, total, total ? called/total : 0}') && set -- $genotype_counts && called_genotypes=$1 && total_genotypes=$2 && call_rate=$3 && awk -v observed="$call_rate" -v required="0.7" 'BEGIN{exit !(observed >= required)}' && printf '{"producer":"bcftools","bcf_source":"out/genotyping.bcf","likelihood_field":"PL","posterior_field":"GP","posterior_derivation":"bcftools_tag2tag_PL_to_GP"}
' > out/genotyping.gl.json && printf '{"caller":"bcftools","reference":"","sites":"","regions":"","bcf":"out/genotyping.bcf","vcf":"out/genotyping.vcf.gz","tbi":"out/genotyping.vcf.gz.tbi","minimum_posterior":0.8,"minimum_call_rate":0.7,"posterior_derivation":"bcftools_tag2tag_PL_to_GP"}
' > out/genotyping.summary.json && printf '{"variant_count":%s,"sample_count":%s,"confident_called_genotypes":%s,"total_genotypes":%s,"minimum_posterior":0.8,"confident_call_rate":%s}
' "$variant_count" "$sample_count" "$called_genotypes" "$total_genotypes" "$call_rate" > out/stage_metrics.json && printf '{"status":"ok","producer":"bam.genotyping","caller":"bcftools","output_bcf":"out/genotyping.bcf","output_vcf":"out/genotyping.vcf.gz"}
' > out/genotyping.json
